    (l, 1, 'listen', 'Achtung am Gleis drei: Der Regionalexpress nach Hannover hat heute zwanzig Minuten Verspätung.', 'كم دقيقة تأخير القطار؟', null, null, '["20", "3", "30", "12"]'::jsonb, 0),
